import{_ as o,o as t,c as a,a2 as n}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Your account","description":"","frontmatter":{},"headers":[],"relativePath":"online/account.md","filePath":"online/account.md","lastUpdated":1792570296000}'),r={name:"online/account.md"};function s(i,e,c,l,d,u){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="your-account" tabindex="-1">Your account <a class="header-anchor" href="#your-account" aria-label="Permalink to &quot;Your account&quot;">​</a></h1><p>An online account keeps your searches, analyses, reviews, saved keys, and credits together. The Community edition you install yourself does not need a PaperSeek account.</p><h2 id="create-an-account" tabindex="-1">Create an account <a class="header-anchor" href="#create-an-account" aria-label="Permalink to &quot;Create an account&quot;">​</a></h2><ol><li>Click <strong>Not signed in</strong> at the bottom of the sidebar, then <strong>Create account</strong>.</li><li>Enter your email address and send the verification code.</li><li>Enter the six-digit code from the email.</li><li>Set and confirm a password.</li></ol><p>Use at least eight characters, and follow any further requirements the form shows.</p><h2 id="sign-in" tabindex="-1">Sign in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign in&quot;">​</a></h2><p>Sign in with your email and password, with a one-time email code, or with GitHub, Hugging Face, or ModelScope when they are offered. Signing in with a provider only signs you in to PaperSeek; it does not let PaperSeek use that provider&#39;s models.</p><p>If you use more than one sign-in method, check the email and account ID in <strong>Settings › User</strong> before continuing. Two different email addresses do not share history.</p><h2 id="settings-›-user" tabindex="-1">Settings › User <a class="header-anchor" href="#settings-›-user" aria-label="Permalink to &quot;Settings › User&quot;">​</a></h2><p>Open it from the account menu (<strong>Account &amp; credits</strong>) or from <strong>Settings</strong>.</p><ul><li><strong>Account</strong> shows your email and account ID. The ID is masked; use <strong>Show</strong> or <strong>Copy</strong> when contacting support. It is not an API key.</li><li><strong>Credits</strong> shows today&#39;s remaining credits, the refill time, and what each task uses. See <a href="./credits">Service &amp; credits</a>.</li><li><strong>Sign-in methods</strong> links or unlinks GitHub, Hugging Face, and ModelScope, and sets a password for an account created without one. Unlinking keeps your history.</li><li><strong>Data management</strong>: <ul><li><strong>Clear keys</strong> deletes every model connection and data-source key saved to your account. Type <code>clear saved keys</code> to confirm. Submitted tasks are not affected.</li><li><strong>Clear history</strong> deletes all searches, analyses, and reviews with their exported files; type <code>clear</code> to confirm. Running tasks are stopped first. Credit records are kept. This cannot be undone.</li></ul></li></ul><p>Signing out does not stop tasks that are already running.</p><h2 id="email-or-password-problems" tabindex="-1">Email or password problems <a class="header-anchor" href="#email-or-password-problems" aria-label="Permalink to &quot;Email or password problems&quot;">​</a></h2><ul><li>Check spam and the spelling of your email address.</li><li>Use the most recent code; requesting a new code can replace the earlier one.</li><li>If you forgot your password, choose <strong>Email code</strong> in the sign-in dialog. Signing in with a code does not change your password.</li><li>If saving the password fails, note the error and the time and try again. Never send your password or verification code to anyone, including support.</li></ul><p>A temporary error during registration is no reason to create several accounts. See <a href="./../reference/troubleshooting">Troubleshooting</a>.</p>',15)])])}const p=o(r,[["render",s]]);export{g as __pageData,p as default};
